// OAuth authorization server ------------------------------------------------
// Every *_hash argument is an HMAC hex digest, never a plaintext code or
// token. Postgres runs at READ COMMITTED: a conditional UPDATE waits on the
// row lock and re-checks its predicate, so exactly one writer wins.
func (q *Queries) CreateOAuthAuthRequest(ctx context.Context, arg CreateOAuthAuthRequestParams) error {
	_, err := q.db.Exec(ctx, createOAuthAuthRequest,
		arg.ID,
		arg.ClientID,
		arg.RedirectUri,
		arg.Resource,
		arg.Scopes,
		arg.OfflineAccess,
		arg.CodeChallenge,
		arg.State,
		arg.ExpiresAt,
		arg.CreatedAt,
	)
	return err
}

